export const YUGI_SKILLS={magician:{cooldown:13,cast:.6,duration:1.05},kuriboh:{cooldown:14,cast:.5,duration:.9},skull:{cooldown:18,cast:.85,duration:1.3},darkmagic:{cooldown:10,cast:.7,duration:1.1},card:{cast:.3,duration:.65}};
function summon(duel,f,kind,seconds){f.summons=f.summons.filter(s=>s.kind!==kind);const side=kind==='kuriboh'?-1:1,s=duel.clampPosition({kind,uid:f.uid+'-summon-'+(++f.summonSerial),ownerUid:f.uid,team:f.team,x:f.x-f.face*55,y:f.y+side*45,born:duel.tick,expires:duel.tick+seconds*60,nextAttack:duel.tick+40,face:f.face,state:'idle'});f.summons.push(s);duel.event('summonAppear',f,{kind,x:s.x,y:s.y});return s;}
function shoot(duel,f,s,t,strong=false){const dx=t.x-s.x,dy=t.y-s.y,d=Math.hypot(dx,dy)||1;s.face=Math.sign(dx)||s.face;s.attackUntil=duel.tick+35;s.strong=strong;duel.shots.push({id:f.id,ownerUid:f.uid,kind:'magic',summonKind:'dark_magician',skill:'darkmagic',requiresOwnerAlive:true,damage:strong?220:90,radius:strong?32:24,x:s.x+dx/d*32,y:s.y+dy/d*32,vx:dx/d*(strong?600:440),vy:dy/d*(strong?600:440),life:2.4,impactEvent:'yugiImpact'});duel.event('summonFire',f,{kind:s.kind,x:s.x,y:s.y,strong});}
export const yugi={name:'Yami Yugi',assets:['yugi','dark_magician','kuriboh','summoned_skull','dark_magician_vfx','kuriboh_vfx','summoned_skull_vfx'],stats:{hp:900,speed:185,melee:50,skillPower:100,cooldown:100,dodgeChance:0,blinkChance:0},
 init(f){f.summons=[];f.summonSerial=0;for(const [key,delay] of Object.entries({magician:0,kuriboh:2,skull:5,darkmagic:3})){f[key+'Cd']=delay*f.cooldownFactor;f.skillUses[key]=0;}},
 onAct(f,state){if(YUGI_SKILLS[state]&&state!=='card'){f[state+'Cd']=YUGI_SKILLS[state].cooldown*f.cooldownFactor;f.skillUses[state]++;}if(state==='card')f.cd=.9*f.cooldownFactor;},
 tick(f,dt){for(const key of ['magician','kuriboh','skull','darkmagic'])f[key+'Cd']=Math.max(0,f[key+'Cd']-dt);},
 absorbDamage(duel,f,damage){const s=f.summons.find(s=>s.kind==='kuriboh'&&duel.tick<s.expires&&s.shield>0);if(!s)return damage;const amount=Math.min(damage,s.shield);s.shield-=amount;if(amount)duel.event('kuribohBlock',f,{x:f.x,y:f.y,value:amount});if(s.shield<=0){f.summons=f.summons.filter(x=>x!==s);duel.event('summonDespawn',f,{kind:s.kind,x:s.x,y:s.y});}return damage-amount;},
 onDeath(duel,f){for(const s of f.summons)duel.event('summonDespawn',f,{kind:s.kind,x:s.x,y:s.y});f.summons=[];duel.shots=duel.shots.filter(s=>!(s.ownerUid===f.uid&&s.requiresOwnerAlive));},
 beforeStep(duel,hits){for(const f of duel.fighters){if(f.id!=='yugi'||f.hp<=0)continue;for(const s of f.summons){if(duel.tick>=s.expires){duel.event('summonDespawn',f,{kind:s.kind,x:s.x,y:s.y});continue;}const target=duel.pickTarget(f);if(!target)continue;const age=duel.tick-s.born;if(age<30)continue;const protect=s.kind==='kuriboh',dx=target.x-s.x,dy=target.y-s.y,d=Math.hypot(dx,dy)||1;
 const goal=protect?{x:f.x-f.face*38,y:f.y-30}:d>310?target:Math.hypot(s.x-f.x,s.y-f.y)>240?f:null;s.state='idle';if(goal){const gx=goal.x-s.x,gy=goal.y-s.y,dist=Math.hypot(gx,gy)||1;if(dist>25){const move=Math.min(dist,210/60);s.x+=gx/dist*move;s.y+=gy/dist*move;s.state='run';}}s.face=Math.sign(dx)||s.face;duel.clampPosition(s);
 if(!protect&&duel.tick>=s.nextAttack&&d<650){if(s.kind==='dark_magician'){shoot(duel,f,s,target);s.nextAttack=duel.tick+78;}else{s.attackUntil=duel.tick+40;s.nextAttack=duel.tick+90;for(const t of duel.fighters)if(t.hp>0&&duel.isEnemy(f,t)&&Math.hypot(t.x-target.x,t.y-target.y)<120)hits.push({target:t,source:f,value:110});duel.event('skullLightning',f,{x:target.x,y:target.y});}}}f.summons=f.summons.filter(s=>duel.tick<s.expires);}},
 updateAction(duel,f,o){const spec=YUGI_SKILLS[f.state];if(!spec)return false;if(f.age>=spec.cast&&!f.hit){f.hit=true;if(f.state==='magician')summon(duel,f,'dark_magician',10);else if(f.state==='kuriboh'){const s=summon(duel,f,'kuriboh',6);s.shield=Math.round(280*f.skillPower/100);}else if(f.state==='skull')summon(duel,f,'summoned_skull',5);else if(f.state==='darkmagic'){const s=f.summons.find(s=>s.kind==='dark_magician'&&duel.tick<s.expires);if(s)shoot(duel,f,s,o,true);}else if(f.state==='card'){const dx=o.x-f.x,dy=o.y-f.y,d=Math.hypot(dx,dy)||1;duel.shots.push({id:f.id,ownerUid:f.uid,kind:'card',damage:f.melee,radius:20,x:f.x+dx/d*30,y:f.y+dy/d*30,vx:dx/d*480,vy:dy/d*480,life:1.2,impactEvent:'yugiImpact'});duel.event('fire',f,{skill:'card'});}}if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;},
 chooseSkill(duel,f,o,dx,dy,d){if(f.magicianCd===0&&!f.summons.some(s=>s.kind==='dark_magician')){duel.act(f,'magician',dx,dy);return true;}for(const key of ['kuriboh','skull','darkmagic'])if(f[key+'Cd']===0&&d<600&&(key!=='darkmagic'||f.summons.some(s=>s.kind==='dark_magician'))){duel.act(f,key,dx,dy);return true;}if(f.cd===0&&d<360){duel.act(f,'card',dx,dy);return true;}return false;}
};
export function yugiPose(f,hurt=false){const state=hurt?'hurt':f.state,row=({idle:0,run:1,melee:3,dash:5,guard:5,hurt:6,defeat:7,magician:4,kuriboh:3,skull:4,darkmagic:4,card:3})[state]??0,spec=YUGI_SKILLS[state];return {row,frame:state==='defeat'?5:spec?Math.min(5,Math.floor(f.age/spec.duration*6)):Math.floor(f.age*9)%6};}
